/* ГЕНЕРАТОР ДАННЫХ. Кладёт на лист правдоподобную таблицу — чтобы было на
   чём проверять формулы, сводные и скорость. Показывает поля «число», «дата»,
   «переключатель» и ВИДИМОСТЬ ПО УСЛОВИЮ: столбцы вручную появляются, только
   когда выбран набор «Свой».

   Случайность с зерном: одно и то же зерно даёт одну и ту же таблицу — иначе
   проверку не повторить. */

const ИМЕНА = 'Анна Борис Вера Глеб Дарья Егор Жанна Захар Ирина Кирилл Лариса Максим Нина Олег Полина Роман Светлана Тимур Ульяна Фёдор'.split(' ');
const ФАМИЛИИ = 'Иванов Петров Сидоров Кузнецов Смирнов Попов Лебедев Козлов Новиков Морозов Волков Соколов Зайцев Павлов Семёнов'.split(' ');
const ГОРОДА = 'Москва Петербург Новосибирск Екатеринбург Казань Нижний_Новгород Челябинск Самара Омск Ростов Уфа Красноярск Воронеж Пермь Волгоград'.split(' ');
const КОМПАНИИ = 'Ромашка Вектор Эталон Азимут Гранит Меридиан Каскад Спектр Оптима Пирамида'.split(' ');
const ТОВАРЫ = 'Стол Стул Шкаф Полка Лампа Ковёр Диван Кресло Тумба Зеркало'.split(' ');
const СТАТУСЫ = ['новый', 'в работе', 'оплачен', 'отгружен', 'закрыт'];

/* свой генератор случайных: с зерном повторяется */
function поток(зерно){
  let с = (зерно >>> 0) || 1;
  return function(){ с ^= с << 13; с ^= с >>> 17; с ^= с << 5; с >>>= 0; return с / 4294967296; };
}
const выбрать = (сл, список) => список[Math.floor(сл() * список.length)];
const целое = (сл, от, до) => от + Math.floor(сл() * (до - от + 1));

const НАБОРЫ = {
  'Люди': ['Имя:имя', 'Фамилия:фамилия', 'Город:город', 'Почта:почта', 'Телефон:телефон', 'Возраст:число(18,65,0)'],
  'Заказы': ['Номер:номер', 'Дата:дата', 'Клиент:компания', 'Товар:товар', 'Количество:число(1,50,0)',
             'Цена:число(100,9000,2)', 'Статус:статус'],
  'Числа': ['A:число(0,1000,2)', 'B:число(0,1000,2)', 'C:число(-500,500,2)', 'D:число(0,1,4)'],
  'Даты': ['Дата:дата', 'День недели:деньНедели', 'Месяц:месяц', 'Значение:число(0,100,1)'],
};

/* Описание столбца «Подпись:тип» → {имя, тип, доводы} */
function столбец(строка){
  const т = String(строка);
  const двоеточие = т.lastIndexOf(':');
  const имя = двоеточие > 0 ? т.slice(0, двоеточие).trim() : т.trim();
  const хвост = двоеточие > 0 ? т.slice(двоеточие + 1).trim() : 'слово';
  const м = /^([А-Яа-яЁёA-Za-z]+)\s*(?:\(([^)]*)\))?$/.exec(хвост);
  return {имя: имя, тип: м ? м[1] : 'слово', доводы: м && м[2] ? м[2].split(',').map(x => x.trim()) : []};
}

function значение(с, сл, номер, началоДат, деньДат){
  const д = с.доводы;
  switch(с.тип){
    case 'имя':        return выбрать(сл, ИМЕНА);
    case 'фамилия':    return выбрать(сл, ФАМИЛИИ);
    case 'город':      return выбрать(сл, ГОРОДА).replace('_', ' ');
    case 'компания':   return 'ООО «' + выбрать(сл, КОМПАНИИ) + '»';
    case 'товар':      return выбрать(сл, ТОВАРЫ);
    case 'статус':     return выбрать(сл, СТАТУСЫ);
    case 'почта':      return (выбрать(сл, ИМЕНА) + '.' + номер).toLowerCase() + '@example.org';
    case 'телефон':    return '+7 9' + целое(сл, 10, 99) + ' ' + целое(сл, 100, 999) + '-' + целое(сл, 10, 99) + '-' + целое(сл, 10, 99);
    case 'номер':      return номер;
    case 'слово':      return выбрать(сл, ТОВАРЫ).toLowerCase();
    case 'список':     return д.length ? выбрать(сл, д) : '';
    case 'дано':       return д.length ? д[0] : '';
    case 'флаг':       return сл() < 0.5;
    case 'деньНедели': return ['понедельник','вторник','среда','четверг','пятница','суббота','воскресенье'][целое(сл, 0, 6)];
    case 'месяц':      return ['январь','февраль','март','апрель','май','июнь','июль','август','сентябрь','октябрь','ноябрь','декабрь'][целое(сл, 0, 11)];
    case 'дата':       return началоДат + целое(сл, 0, Math.max(0, деньДат));
    case 'число': {
      const от = д.length > 0 ? +д[0] : 0, до = д.length > 1 ? +д[1] : 1000;
      const знаков = д.length > 2 ? +д[2] : 2;
      const з = от + сл() * (до - от);
      return +з.toFixed(Math.max(0, Math.min(10, знаков)));
    }
    default: return '';
  }
}

async function Заполнить(){
  const п = параметры({});
  const набор = п.набор || 'Люди';
  const описания = (набор === 'Свой'
      ? String(п.столбцы || '').split(/\r?\n/).filter(с => с.trim())
      : НАБОРЫ[набор] || []).map(столбец);
  if(!описания.length){ панель.сообщение('Ни одного столбца — опишите их «Подпись:тип»'); return; }
  const рядов = Math.max(1, Math.min(1000000, +п.рядов || 100));
  const сл = поток(+п.зерно || 12345);
  const началоДат = дата(п.сНачала || '01.01.2024');
  const деньДат = дата(п.поКонец || '31.12.2026') - началоДат;

  const строки = [];
  if(п.заголовки) строки.push(описания.map(с => с.имя));
  for(let i = 1; i <= рядов; i++) строки.push(описания.map(с => значение(с, сл, i, началоДат, деньДат)));

  const адрес = String(п.клетка || 'A1').trim().toUpperCase() || 'A1';
  const л = лист();
  /* область задаём целиком: «записать» не выходит за её края */
  const область = адрес + ':' + смещение(адрес, описания.length - 1, строки.length - 1);
  л.диапазон(область).записать(строки);
  /* даты показываем датами, а не числами */
  описания.forEach((с, i) => { if(с.тип === 'дата'){
    const столб = смещение(адрес, i, п.заголовки ? 1 : 0);
    л.диапазон(столб + ':' + смещение(адрес, i, строки.length - 1)).формат = 'dd.mm.yyyy';
  }});
  панель.сообщение('Записано строк: ' + рядов + ', столбцов: ' + описания.length + ' — с ' + адрес);
  л.диапазон(область).выделить();
}

/* A1 + n столбцов и m строк → адрес */
function смещение(адрес, докуда, вниз){
  const м = /^([A-Z]+)(\d+)$/.exec(адрес) || ['', 'A', '1'];
  let столбец = 0;
  for(const з of м[1]) столбец = столбец * 26 + (з.charCodeAt(0) - 64);
  столбец += докуда;
  let имя = '';
  while(столбец > 0){ const о = (столбец - 1) % 26; имя = String.fromCharCode(65 + о) + имя; столбец = (столбец - о - 1) / 26; }
  return имя + (+м[2] + вниз);
}

async function Очистить(){
  const в = книга.выделение;
  if(!в){ панель.сообщение('Сначала выделите, что очистить'); return; }
  if(!(await диалог.вопрос('Очистить ' + в.область + '?'))) return;
  const л = лист(в.лист), пусто = [];
  for(let r = в.r1; r <= в.r2; r++) пусто.push(new Array(в.c2 - в.c1 + 1).fill(null));
  л.диапазон(в.область).записать(пусто);
  панель.сообщение('Очищено: ' + в.область);
}
